import requests, json
names=['tetracycline','doxycycline','oxytetracycline','chlortetracycline','minocycline']
for n in names:
 u=f'https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/name/{n}/property/IUPACName,IsomericSMILES,CanonicalSMILES,MolecularFormula,MolecularWeight/JSON'
 r=requests.get(u,timeout=20)
 print('\n',n,r.status_code)
 if r.ok:
  p=r.json()['PropertyTable']['Properties'][0]
  print(json.dumps(p,indent=2))
 else: print(r.text[:200])

